function Admin({onNotice}:{onNotice:(message:string)=>void}){
  const [data,setData]=useState<any>(null),[days,setDays]=useState(14),[error,setError]=useState(''),[busy,setBusy]=useState(false),[label,setLabel]=useState(''),[newCode,setNewCode]=useState(''),[testAccount,setTestAccount]=useState(false),[creating,setCreating]=useState(false);
  async function load(){setBusy(true);setError('');try{setData(await api(`/admin/summary?days=${days}`));}catch(e){setError(errorText(e));}finally{setBusy(false);}}
  useEffect(()=>{void load();},[days]);
  async function createUser(e:React.FormEvent){e.preventDefault();setCreating(true);setError('');try{const user=await api('/admin/users','POST',{label,isTest:testAccount});setNewCode(user.code);setLabel('');await load();}catch(e){setError(errorText(e));}finally{setCreating(false);}}
  async function disable(id:string,value:boolean){try{await api(`/admin/users/${id}`,'PATCH',{disabled:value});await load();onNotice(value?'Testzugang gesperrt.':'Testzugang wieder aktiv.');}catch(e){setError(errorText(e));}}
  async function iphoneLink(id:string){try{const r=await api('/admin/users/'+id+'/iphone-invite','POST',{});setInvite({url:r.url,expiresAt:r.expiresAt});onNotice('Persönlicher iPhone-Link erstellt. Er ersetzt den vorherigen Link für diese Person.');}catch(e){setError(errorText(e));}}
  const [invite,setInvite]=useState<{url:string;expiresAt:number}|null>(null);
  const ratingCount=(name:string)=>data?.ratings.find((r:any)=>r.rating===name)?.n||0;
  const rated=ratingCount('yes')+ratingCount('partly')+ratingCount('no');
  const savedTime=data?.feedback.filter((f:any)=>f.minutes!==null)||[];
  const categories={reply:'Nachrichten',letter:'Briefe',write:'Texte',ask:'Fragen'};
  return <main id="main" className="admin-main"><div className="admin-top"><div><a href="/" className="back-button"><ArrowLeft size={18}/>Zur App</a><div className="admin-eyebrow"><span className="status-dot"/>Geschützter Betreiberbereich</div><h1>Was macht den Alltag leichter?</h1><p>Dein Pilot, mit echten Rückmeldungen und klaren Grenzen.</p></div><div className="admin-tools"><label className="sr-only" htmlFor="period">Zeitraum</label><select id="period" value={days} onChange={e=>setDays(Number(e.target.value))}><option value={7}>Letzte 7 Tage</option><option value={14}>Letzte 14 Tage</option><option value={30}>Letzte 30 Tage</option></select><button className="icon-button" disabled={busy} onClick={()=>void load()} aria-label="Auswertung aktualisieren"><RefreshCw size={20} className={busy?'spin':''}/></button><a className="secondary" href={`/api/admin/export?days=${days}`} download><Download size={18}/>Export</a></div></div>{error&&<p role="alert" className="error-box">{error}</p>}{!data?<div className="page-loading"><LoaderCircle className="spin"/>Auswertung wird geladen …</div>:<><p className="admin-window">{date(data.since)} bis {date(data.until)} Uhr · Europe/Berlin · Techniktestkonten ausgeschlossen</p><div className="metric-grid"><div className="metric"><span>Aktive Testpersonen</span><strong>{data.use.active}<small> / {data.counts.testers}</small></strong><p>{data.repeat} an mindestens zwei Tagen aktiv</p></div><div className="metric"><span>KI-Antworten</span><strong>{data.use.completed}<small> / {data.use.attempts}</small></strong><p>Erfolgreich beantwortete Versuche</p></div><div className="metric"><span>Als hilfreich bewertet</span><strong>{ratingCount('yes')}<small> / {rated}</small></strong><p>{rated?'Von ausdrücklich bewerteten Antworten':'Noch keine Bewertungen'}</p></div><div className="metric"><span>Modellkosten im Pilot</span><strong className="cost-number">{dollars(data.use.costMicros)}</strong><p>Schätzung · {data.use.unknownUsage||0} unbekannte Verbräuche reserviert</p></div></div><div className="admin-columns"><section className="admin-panel"><h2>Wofür wird Alltag genutzt?</h2><p className="panel-subtitle">Anfragen je Aufgabe – einschließlich Wiederholungen und Fehlern.</p>{data.categories.length?<div className="usage-bars">{data.categories.map((c:any)=><div className="usage-row" key={c.category}><div><strong>{categories[c.category as Category]}</strong><span>{c.attempts} Anfragen · {c.people} Personen</span></div><div className="bar-track"><span style={{width:`${c.attempts/Math.max(...data.categories.map((v:any)=>v.attempts))*100}%`}}/></div></div>)}</div>:<Empty text="Noch keine Pilotanfragen. Gib deinen Eltern ihren persönlichen Code und lass sie mit einer echten kleinen Aufgabe anfangen."/>}<div className="panel-bottom"><span>{data.use.failed} technische Fehler</span><span>{data.actions.find((a:any)=>a.type==='copy')?.n||0} Antworten kopiert</span><span>{data.actions.find((a:any)=>a.type==='read_aloud')?.n||0} Vorlesen gestartet</span></div>{data.errors.map((e:any)=><p className="small-note" key={e.error_code}>Fehler {e.error_code||'unbekannt'}: {e.n}</p>)}</section><section className="admin-panel"><h2>Kommt die Hilfe an?</h2><div className="rating-totals"><div><Smile size={24}/><strong>{ratingCount('yes')}</strong><span>Ja</span></div><div><Meh size={24}/><strong>{ratingCount('partly')}</strong><span>Teilweise</span></div><div><Frown size={24}/><strong>{ratingCount('no')}</strong><span>Noch nicht</span></div></div><div className="time-note"><strong>{savedTime.reduce((n:number,f:any)=>n+f.minutes,0)} Minuten</strong><p>freiwillig geschätzte Zeitersparnis aus {savedTime.length} Rückmeldungen. Keine gemessene Zeitersparnis.</p></div><p className="small-note">Anfragen, hilfreiche Antworten und tatsächlich erledigte Aufgaben sind unterschiedliche Größen. Unbewertete Antworten werden nicht als Erfolg gezählt.</p></section></div><section className="admin-panel"><h2>Sprechen und direkt teilen</h2><div className="guide-metric-grid"><div><strong>{data.voice.completed}<small> / {data.voice.attempts}</small></strong><span>Sprachaufnahmen in Text umgewandelt</span></div><div><strong>{data.entries.filter((e:any)=>e.entry.startsWith('shared_')).reduce((n:number,e:any)=>n+e.requests,0)}</strong><span>Aufgaben mit geteilter Quelle abgeschickt</span></div><div><strong>{data.entries.filter((e:any)=>['voice','shared_voice'].includes(e.entry)).reduce((n:number,e:any)=>n+e.requests,0)}</strong><span>KI-Aufgaben mit Sprache abgeschickt</span></div></div><p className="small-note">Umwandlung, abgeschickte Aufgabe und tatsächlicher Nutzen sind getrennt. Geteilte Quellen werden erst beim Abschicken gezählt, nicht beim bloßen Öffnen. Sprachkosten sind in den Modellkosten enthalten; {data.voice.unknownUsage} unbekannte Verbräuche sind vorsichtig reserviert. Keine Audioaufnahme oder privaten Transkripte in dieser Auswertung.</p></section><section className="admin-panel guide-metrics"><h2>Wie hilft der Nachrichtenhelfer?</h2><p className="panel-subtitle">Abgeschickte Aufgaben im gewählten Zeitraum. Testkonten sind ausgeschlossen.</p><div className="guide-metric-grid"><div><strong>{data.guide.completed}<small> / {data.guide.submitted}</small></strong><span>Aufgaben technisch beantwortet</span></div><div><strong>{data.guide.drafts.copied}<small> / {data.guide.drafts.answers}</small></strong><span>Antwortentwürfe kopiert</span></div><div><strong>{data.guide.drafts.used}<small> / {data.guide.drafts.answers}</small></strong><span>Freiwillig als verwendet bestätigt</span></div></div>{data.guide.intents.length?<div className="guide-intent-stats">{data.guide.intents.map((i:{intent:Intent;n:number})=><span key={i.intent}>{intentNames[i.intent]} <strong>{i.n}</strong></span>)}</div>:<Empty text="Noch keine abgeschickte Aufgabe im Nachrichtenhelfer. Welche Wünsche am häufigsten vorkommen, sehen wir erst nach echter Nutzung."/>}<p className="small-note">Entwürfe enthalten auch Folgefassungen; Erklärungen zählen nicht als Entwürfe. Kopieren und Verwenden werden je Antwort einmal gezählt. „Verwendet“ ist eine Selbstauskunft, kein Versandbeleg. Abbrüche vor dem Abschicken sind hier nicht erfasst. Bearbeitete Texte bleiben privat.</p></section><section className="admin-panel"><div className="panel-heading"><div><h2>Was hat gehakt?</h2><p className="panel-subtitle">Bewertungen und freiwillige Rückmeldungen an dich.</p></div><MessageCircle size={23}/></div>{data.feedback.length?<div className="feedback-list">{data.feedback.map((f:any)=><article key={f.id} className="feedback-item"><div><strong>{f.label}</strong><time>{date(f.created_at)}</time>{f.rating&&<span className={`feedback-badge ${f.rating}`}>{{yes:'Hilfreich',partly:'Teilweise',no:'Noch nicht'}[f.rating as Rating]}</span>}</div>{f.issue&&<p className="issue-tag">{{start:'Einstieg unklar',unclear:'Antwort zu kompliziert',wrong:'Antwort unpassend',technical:'Technisches Problem',other:'Anderer Hinweis'}[f.issue as string]||f.issue}</p>}{f.note&&<p className="feedback-note">{f.note}</p>}{f.minutes!==null&&<small>{f.minutes} Minuten selbst geschätzt</small>}</article>)}</div>:<Empty text="Hier landen die Rückmeldungen deiner Testpersonen. Eine fehlende Rückmeldung ist noch kein Zufriedenheitsbeleg."/>}</section><div className="admin-columns"><section className="admin-panel"><h2>Deine Testpersonen</h2><div className="tester-list">{data.users.map((u:any)=><div key={u.id} className="tester"><div><strong>{u.label}{u.is_test?<span className="test-tag">Techniktest</span>:null}</strong><p>{u.disabled?'Gesperrt':u.accepted_at?'Test gestartet':'Noch nicht gestartet'} · {u.attempts} Anfragen</p><small>{u.share_content?'Texte freiwillig freigegeben':'Gesprächsinhalte privat'}</small></div><div className="tester-actions">{!u.disabled&&<button className="text-button" onClick={()=>void iphoneLink(u.id)}>iPhone-Link erstellen</button>}<button className="text-button" onClick={()=>void disable(u.id,!u.disabled)}>{u.disabled?'Entsperren':'Sperren'}</button></div></div>)}</div></section><section className="admin-panel">{invite&&<div className="new-code"><strong>Persönlicher iPhone-Einladungslink</strong><p>Einmal verwendbar bis {new Date(invite.expiresAt).toLocaleDateString('de-DE')}. Nur an die ausgewählte Person weitergeben.</p><input aria-label="Persönlicher iPhone-Link" readOnly value={invite.url}/><button className="secondary" onClick={()=>{void navigator.clipboard.writeText(invite.url).then(()=>onNotice('iPhone-Link kopiert.')).catch(()=>onNotice('Bitte markiere den Link zum Kopieren.'));}}><Copy size={17}/>iPhone-Link kopieren</button></div>}<h2>Jemanden zum Test einladen</h2><p className="panel-subtitle">Ein eigener Code trennt die Gespräche und die Auswertung.</p><form className="form-stack" onSubmit={createUser}><label>Anzeigename<input value={label} onChange={e=>setLabel(e.target.value)} placeholder="Zum Beispiel: Testperson 3" minLength={2} maxLength={40} required/></label><label className="check-label"><input type="checkbox" checked={testAccount} onChange={e=>setTestAccount(e.target.checked)}/><span>Techniktest – aus Pilotzahlen ausschließen</span></label><button className="primary" disabled={creating}>{creating?<LoaderCircle className="spin" size={18}/>:<UserPlus size={18}/>}Testcode erstellen</button></form>{newCode&&<div className="new-code"><strong>Nur jetzt sichtbar: persönlicher Testcode</strong><code>{newCode}</code><button className="secondary" onClick={()=>{void navigator.clipboard.writeText(`Dein persönlicher Alltag-Testzugang:\n${window.location.origin}\nCode: ${newCode}`).then(()=>onNotice('URL und Code sind kopiert.')).catch(()=>onNotice('Bitte markiere den Code zum Kopieren.'));}}><Copy size={17}/>URL und Code kopieren</button></div>}</section></div><section className="admin-panel"><h2>Freiwillig freigegebene Gesprächsinhalte</h2><p className="panel-subtitle">Nur Nachrichten, die bei aktiver Freigabe entstanden sind. Nach einem Widerruf sind sie hier nicht mehr abrufbar. Fotos werden nicht gespeichert.</p>{data.contents.length?<div className="shared-content">{data.contents.map((m:any)=><details key={m.id}><summary><span>{m.label} · {m.role==='user'?'Eingabe':'Antwort'} · {categories[m.category as Category]}</span><time>{date(m.created_at)}</time></summary><p>{m.content}</p></details>)}</div>:<Empty text="Aktuell sind keine Gesprächsinhalte freigegeben. Die App funktioniert auch ohne diese Freigabe."/>}</section><section className="admin-panel budget-panel"><div><h2>Der Test bleibt überschaubar.</h2><p>Diesen Monat insgesamt {dollars(data.budget.costMicros)} von 30,00 USD Budget · {data.budget.attempts} KI-Versuche und {data.budget.voiceAttempts} Sprachumwandlungen inklusive Techniktests. Erneuerung am ersten Tag des nächsten Monats (UTC). Maximal 25 KI-Anfragen und 25 Sprachaufnahmen pro Person und UTC-Tag, zwei gleichzeitig.</p><p className="small-note">{data.model} · Preise vom 17.10.2026: Input 2,00 USD, gecachter Input 0,10 USD und Output 10,00 USD je Million Tokens. Höchstens zwölf Textnachrichten Kontext. Ohne automatischen Internetzugriff. Laufende oder unbekannte Textanfragen reservieren 1 USD, Sprachaufnahmen 0,03 USD; gemeldeter Verbrauch ersetzt die Reservierung. Die tatsächliche OpenAI-Abrechnung kann abweichen.</p></div><ShieldCheck size={38}/></section></> }</main>;
}
function Empty({text}:{text:string}){return <div className="admin-empty"><span className="empty-dot"/><p>{text}</p></div>;}

createRoot(document.getElementById('root')!).render(<React.StrictMode>{window.location.pathname==='/iphone'?<IPhoneInstall/>:<App/>}</React.StrictMode>);
